void mainImage(out vec4 O, in vec2 U)
{
    O=pow(texture(iChannel0, U/iResolution.xy),vec4(1./2.2));
}

#define BOUNCES 2
#define MAX_STEPS 20
#define MAX_SHADOW_STEPS 80

float get_shadow(vec2 o, vec2 d)
{
    float t=0.;
    float k=1.;
    for (int i=0; i<MAX_SHADOW_STEPS; i++)
    {
        vec2 p = o+d*t;
        float dt = scene(p).t;
        t += dt;
        if (t>100.) break;
        if (dt<.001)
        {
            k=0.;
            break;
        }
    }

    return k;
}

void mainImage(out vec4 O, in vec2 U)
{
    vec2 ires=iResolution.xy;
    float scale = 4.;
    vec2 p = scale*((U-.5*ires.xy)/ires.y);

    vec3 c = vec3(0);
    float h=hash12(U+floor(mod(float(iFrame), 600.))*ires)*360.;

    vec2 o = p, d;
    float t;

    vec2 mv= scale*(iMouse.xy-.5*ires.xy)/ires.y;
    vec2 sd=(vec2(
        cos(h), sin(h)
    ));

    bool done = false;
    for (int b=0;b<BOUNCES;b++)
    {
        float t = 0.;
        for (int s=0;s<MAX_STEPS;s++)
        {
            vec2 sp=o+sd*t;
            mat dt_m = scene(sp);
            float dt = dt_m.t;
            t+=dt;

            if (t>100.) 
            {
                c += vec3(.1);
                done = true;
                break;
            };
            if (dt<.001)
            {
                vec2 lv = mv-o;
                float ll = length(lv);
                float a = ll;
                a = 5.5/(a*a);

                vec2 n = get_normal(sp);
                float kD = max(dot(n,lv), 0.);

                //dt_m.c
                vec2 op=o+sd*t;

                float sh = get_shadow(o+n*.1, normalize(mv-op));
                c += dt_m.c*(.1+(vec3(1)*sh*kD*a))/(float(b)+1.);

                o = op;
                sd = reflect(sd, n);

                break;
            }
        }
        if (done) break;
    }
    c /= float(BOUNCES);
    vec4 st = texture(iChannel0, U/ires);
    if (iMouse.z < 0.)
        c = mix(st.rgb,c,1./(float(iFrame)-st.a+1.));
    O = vec4(c,(iMouse.z > 0.)?float(iFrame):st.a);
}

float hash12(vec2 p)
{
	uvec2 q = uvec2(ivec2(p)) * uvec2(1597334673U, 3812015801U);
	uint n = (q.x ^ q.y) * 1597334673U;
	return float(n) * 2.328306437080797e-10;
}

struct mat
{
    bool em;
    vec3 c;
    float t;
};

float sd_circle(vec2 p, float r) {return length(p)-r;}
float sd_box(vec2 p, vec2 b)
{
    vec2 q=abs(p)-b;
    return length(max(q,0.))+min(max(q.x,q.y),0.);
}

mat scene(vec2 p)
{
    mat b = mat(
        false, 
        vec3(1,0,0),
        sd_box(p-vec2(-2,0),vec2(.2,1.))
    );
    mat b2 = mat(
        false, 
        vec3(.5),
        sd_box(p-vec2(2.7,0),vec2(.2,1.))
    );

    mat bc = mat(
        true, 
        vec3(0,1,0),
        sd_circle(p-vec2(1.5,0),.2)
    );
    mat sc = mat(
        true,
        vec3(.25),
        sd_circle(p-vec2(-1,0),.2)
    );

    bool em = (b.t<sc.t) ? b.em : ((bc.t<sc.t) ? bc.em : sc.em);
    vec3 c = (b.t<sc.t) ? b.c : ((bc.t<sc.t) ? bc.c : sc.c);

    return mat(
        em, c, min(min(b.t, b2.t), min(bc.t, sc.t))
    );
}

vec2 get_normal(vec2 p)
{
    const vec2 e = vec2(0., .001);
    return normalize(vec2(
        scene(p+e.yx).t-scene(p-e.yx).t,
        scene(p+e.xy).t-scene(p-e.xy).t
    ));
}
